from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]


def exact(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        raise RuntimeError(f"missing exact patch target: {label}")
    return text.replace(old, new, 1)


def regex(text: str, pattern: str, replacement: str, label: str) -> str:
    new_text, count = re.subn(pattern, lambda _: replacement, text, count=1, flags=re.S)
    if count != 1:
        raise RuntimeError(f"regex patch count {count} for {label}")
    return new_text


